def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a full row or column that acts as the divider.
    divider_row = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if divider_row is not None:
        top = grid[:divider_row]
        bottom = grid[divider_row + 1:]
        if top and bottom:
            return [
                [3 if top[r][c] == bottom[r][c] else 7
                 for c in range(w)]
                for r in range(min(len(top), len(bottom)))
            ]

    divider_col = next(
        (c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))),
        None
    )
    if divider_col is not None:
        left_w = divider_col
        right_w = w - divider_col - 1
        out = []
        for r in range(h):
            row = []
            for c in range(min(left_w, right_w)):
                row.append(3 if grid[r][c] == grid[r][divider_col + 1 + c] else 5)
            out.append(row)
        return out

    return grid
